const vs=`attribute vec3 position;attribute vec3 normal;uniform vec3 center;uniform float yaw,pitch,scale,aspect;varying vec3 n;void main(){vec3 p=position-center;float c=cos(yaw),s=sin(yaw);p=vec3(c*p.x-s*p.y,s*p.x+c*p.y,p.z);c=cos(pitch);s=sin(pitch);p=vec3(p.x,c*p.y+s*p.z,-s*p.y+c*p.z);gl_Position=vec4(p.x/(scale*aspect),p.y/scale,-p.z/(scale*12.),1.);n=normal;}`;
const fs=`precision mediump float;varying vec3 n;uniform vec3 color;uniform float unlit;void main(){float light=.38+.62*abs(dot(n/max(length(n),.00001),normalize(vec3(-.35,-.45,1.))));gl_FragColor=vec4(color*mix(light,1.,unlit),1.);}`;
export class Viewer{
 constructor(canvas){this.canvas=canvas;this.yaw=-.35;this.pitch=.92;this.zoom=1;this.mode='assembled';this.explode=.65;this.selected='';this.focus=false;this.wire=false;const gl=canvas.getContext('webgl',{antialias:true,alpha:true});if(!gl)throw Error('3D preview needs WebGL. Geometry and downloads still work.');this.gl=gl;const shader=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;};this.program=gl.createProgram();gl.attachShader(this.program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(this.program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(this.program);if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error('Preview shader could not link');this.loc={};for(const x of ['yaw','pitch','scale','aspect','center','color','unlit'])this.loc[x]=gl.getUniformLocation(this.program,x);this.pos=gl.getAttribLocation(this.program,'position');this.norm=gl.getAttribLocation(this.program,'normal');this.objects=[];
 let drag=null;canvas.addEventListener('pointerdown',e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag)return;this.yaw+=(e.clientX-drag[0])*.008;this.pitch=Math.max(-Math.PI,Math.min(Math.PI,this.pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];this.draw();});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom=Math.max(.3,Math.min(3,this.zoom*Math.exp(-e.deltaY*.001)));this.draw();},{passive:false});canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','=','Home'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')this.yaw-=.1;if(e.key==='ArrowRight')this.yaw+=.1;if(e.key==='ArrowUp')this.pitch+=.1;if(e.key==='ArrowDown')this.pitch-=.1;if(e.key==='+'||e.key==='=')this.zoom=Math.min(3,this.zoom*1.1);if(e.key==='-')this.zoom=Math.max(.3,this.zoom/1.1);if(e.key==='Home')this.reset();this.draw();});this.resize=new ResizeObserver(()=>this.draw());this.resize.observe(canvas);}
 reset(){this.yaw=-.35;this.pitch=.92;this.zoom=1;this.draw();}
 setModel(m){this.model=m;this.rebuild();}
 rebuild(){if(!this.model)return;const gl=this.gl,m=this.model;for(const o of this.objects){gl.deleteBuffer(o.p);gl.deleteBuffer(o.n);}this.objects=[];
 const add=(verts,norms,color,lines=false)=>{if(!verts.length)return;const p=gl.createBuffer(),n=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,p);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(verts),gl.STATIC_DRAW);gl.bindBuffer(gl.ARRAY_BUFFER,n);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(norms),gl.STATIC_DRAW);this.objects.push({p,n,count:verts.length/3,color,lines});};
 const packing=this.mode==='layout'&&m.p.packPlates;
 let items=packing?m.plates.flatMap((plate,i)=>plate.placements.map((placement,j)=>({part:placement.part,a:placement.yaw*Math.PI/180,i,placement,first:j===0}))):this.mode==='layout'?m.parts.flatMap((part,i)=>[{part,a:0,i},...part.supportMeshes.map(mesh=>({part,a:0,i,supportMesh:mesh}))]):m.instances;
 const bedCount=packing?m.plates.length:m.parts.length,cols=Math.ceil(Math.sqrt(bedCount)),cell=Math.max(m.p.bedX,m.p.bedY)+24;
 this.extent=this.mode==='layout'?cell*Math.max(cols,Math.ceil(bedCount/cols)):m.p.diameter*(this.mode==='exploded'?1.3:1);
 for(const item of items){const {part,a}=item,c=Math.cos(a),s=Math.sin(a),layout=this.mode==='layout',ex=this.mode==='exploded'?this.explode:0,mesh=item.supportMesh||(layout?(packing?part.output:part.print):part.mesh);let tr=[0,0,0];if(layout)tr=[(item.i%cols-(cols-1)/2)*cell,(Math.floor(item.i/cols)-(Math.ceil(bedCount/cols)-1)/2)*cell,0];
 const bedOffset=[...tr];if(layout&&packing){tr[0]+=item.placement.x;tr[1]+=item.placement.y;}
 const V=layout?mesh.v.map(([x,y,z])=>[c*x-s*y+tr[0],s*x+c*y+tr[1],z+tr[2]]):mesh.v.map(q=>scenePoint(m,item,q,ex)),positions=[],normals=[],edges=[];
 for(const f of mesh.f){const [a,b,c]=f.map(i=>V[i]),u=b.map((x,k)=>x-a[k]),v=c.map((x,k)=>x-a[k]),n=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],l=Math.hypot(...n)||1;positions.push(...a,...b,...c);for(let k=0;k<3;k++)normals.push(...n.map(x=>x/l));if(this.wire)edges.push(...a,...b,...b,...c,...c,...a);}
 let color=item.supportMesh?[.90,.43,.30]:part.kind==='panel'?(part.row%2?[.48,.63,.85]:[.72,.73,.76]):part.kind==='hub'?[.88,.65,.34]:part.kind==='mount'?[.35,.48,.64]:part.kind==='clip'?[.95,.58,.25]:part.kind==='feed'?[.42,.70,.62]:[.46,.48,.54];if(this.selected&&part.id!==this.selected)color=color.map(x=>x*.55);if(this.selected===part.id&&!item.supportMesh)color=[.60,.76,1];add(positions,normals,color);if(this.wire)add(edges,new Array(edges.length).fill(0),[.10,.10,.12],true);
 if(layout&&!item.supportMesh&&(!packing||item.first)){const x=m.p.bedX/2,y=m.p.bedY/2,points=[[-x,-y], [x,-y],[x,y],[-x,y]],ev=[];for(let k=0;k<4;k++)for(const v of [points[k],points[(k+1)%4]])ev.push(v[0]+bedOffset[0],v[1]+bedOffset[1],-1);add(ev,new Array(ev.length).fill(0),[.3,.3,.34],true);}
 }
 if(this.mode!=='layout'){if(m.feed&&this.mode==='assembled'){const rods=[];for(const l of m.feed.legs)rods.push(...dishPoint(m,l.lower),...dishPoint(m,l.upper));add(rods,new Array(rods.length).fill(0),[.4,.85,.72],true);this.extent=Math.max(this.extent,m.feed.carrierFace*1.7);}
 const r=m.p.diameter*.65,step=m.p.diameter/10,grid=[];for(let v=-r;v<=r;v+=step)grid.push(-r,v,-18,r,v,-18,v,-r,-18,v,r,-18);add(grid,new Array(grid.length).fill(0),[.13,.13,.15],true);if(this.focus){const f=m.focal,h=m.p.diameter*.015,lines=[-h,0,f,h,0,f,0,-h,f,0,h,f,0,0,f-h,0,0,f+h];for(let z=0;z<f;z+=f/24)lines.push(0,0,z,0,0,z+f/48);const transformed=[];for(let i=0;i<lines.length;i+=3)transformed.push(...dishPoint(m,lines.slice(i,i+3)));add(transformed,new Array(transformed.length).fill(0),[1,.7,.3],true);this.extent=Math.max(this.extent,f*1.65);}}
 const b=sceneBounds(m);this.center=b.min.map((v,k)=>(v+b.max[k])/2);if(this.mode!=='layout')this.extent=Math.max(this.extent,...b.size)*(this.mode==='exploded'?1.15:1);this.draw();}
 draw(){const gl=this.gl;if(!this.model)return;const rect=this.canvas.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1),w=Math.max(1,Math.round(rect.width*dpr)),h=Math.max(1,Math.round(rect.height*dpr));if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;}gl.viewport(0,0,w,h);gl.clearColor(.031,.031,.035,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);gl.useProgram(this.program);gl.uniform1f(this.loc.yaw,this.yaw);gl.uniform1f(this.loc.pitch,this.pitch);gl.uniform1f(this.loc.scale,this.extent*.66/this.zoom*Math.max(1,h/w));gl.uniform1f(this.loc.aspect,w/h);gl.uniform3fv(this.loc.center,this.mode==='layout'?[0,0,0]:(this.center||[0,0,0]));gl.enableVertexAttribArray(this.pos);gl.enableVertexAttribArray(this.norm);for(const o of this.objects){gl.bindBuffer(gl.ARRAY_BUFFER,o.p);gl.vertexAttribPointer(this.pos,3,gl.FLOAT,false,0,0);gl.bindBuffer(gl.ARRAY_BUFFER,o.n);gl.vertexAttribPointer(this.norm,3,gl.FLOAT,false,0,0);gl.uniform3fv(this.loc.color,o.color);gl.uniform1f(this.loc.unlit,o.lines?1:0);gl.drawArrays(o.lines?gl.LINES:gl.TRIANGLES,0,o.count);}}
}
